/**
 * Migration Name: add-image-fields-to-categories
 * Database Type: TENANT
 * Created: 23/10/2026
 *
 * Category images for the ecommerce storefront (plans/2026-10-15-ecommerce-
 * b2b-b2c-plan.txt, P2/P3 UI pass) - categories had NO image column at all
 * (confirmed via SHOW COLUMNS before writing this). One image per category
 * (not a gallery like product_images - a category tile needs exactly one
 * picture), so three plain columns directly on `categories`, same column
 * names/shape as product_images' own image_path/webp_path/thumbnail_path
 * for consistency, generated by the same sharp webp+thumbnail conversion
 * (see categoryImageServices.js).
 */

const columnExists = async (queryInterface, table, column) => {
  const columns = await queryInterface.describeTable(table);
  return Object.prototype.hasOwnProperty.call(columns, column);
};

const COLUMNS = ["image_path", "webp_path", "thumbnail_path"];

export const up = async (queryInterface, Sequelize) => {
  for (const name of COLUMNS) {
    if (await columnExists(queryInterface, "categories", name)) continue;
    await queryInterface.addColumn("categories", name, { type: Sequelize.STRING, allowNull: true });
  }
};

export const down = async (queryInterface) => {
  for (const name of COLUMNS) {
    if (await columnExists(queryInterface, "categories", name)) {
      await queryInterface.removeColumn("categories", name);
    }
  }
};
